import{_ as t,o,c as a,a3 as r}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"Documents — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Documents — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/documents"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Documents — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/documents"}]]},"headers":[],"relativePath":"user-guide/documents.md","filePath":"user-guide/documents.md","lastUpdated":1788633037000}'),s={name:"user-guide/documents.md"};function n(d,e,l,i,c,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="documents-—-user-guide" tabindex="-1">Documents — User Guide <a class="header-anchor" href="#documents-—-user-guide" aria-label="Permalink to &quot;Documents — User Guide&quot;">​</a></h1><h2 id="who-can-use-documents" tabindex="-1">Who can use Documents <a class="header-anchor" href="#who-can-use-documents" aria-label="Permalink to &quot;Who can use Documents&quot;">​</a></h2><p>Your workspace must have <strong>Storage</strong> and <strong>Documents</strong> installed. Documents cannot install without Storage. Your role must include the relevant permissions (<code>view</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>restore</code>, <code>force.delete</code> as needed).</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><ol><li>Open <strong>Marketplace</strong></li><li>Install free <strong>Storage</strong> first (if not already entitled — Team Chat may have installed it for you)</li><li>Install free <strong>Documents</strong> under Operations</li><li>Open <strong>Documents</strong> from the sidebar</li></ol><p>Without Storage, Marketplace blocks Documents install. Uploads also require remaining Storage quota.</p><h2 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List&quot;">​</a></h2><p>Open <strong>Documents</strong> from the sidebar (Operations area).</p><ul><li>Search by title, description, or original file name</li><li>Filter by category, or toggle trash filters (<strong>Active / Include deleted / Deleted only</strong>) when you have <strong>restore</strong></li><li>KPI cards summarize total, categorized, and uncategorized counts</li><li><strong>Delete permanently</strong> requires <code>documents.force.delete</code> (not on default role maps — same posture as Vendors / Assets)</li></ul><h2 id="upload" tabindex="-1">Upload <a class="header-anchor" href="#upload" aria-label="Permalink to &quot;Upload&quot;">​</a></h2><ol><li>Click <strong>New document</strong> (shortcut: <code>n</code> when the list is focused and you have create permission)</li><li>Enter a title (required). Optionally add a description and category</li><li>Optionally link a <strong>Contact</strong>, <strong>Company</strong>, or <strong>Lead</strong> when those modules are installed — use <strong>New</strong> beside a picker to create and select inline when you have create permission</li><li>Choose a file (required on create). Allowed types include common office docs, images, text/CSV, and archives; max <strong>50 MB</strong> per file</li><li>Save — the file is stored on the workspace uploads disk under the tenant Documents directory</li></ol><p>Focus search with <code>Ctrl/⌘+F</code>.</p><h2 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h2><p>Categories are a flat list (no nested folders).</p><ul><li>Create / edit categories from the Documents UI (permissions reuse <code>documents.create</code> / <code>update</code> / <code>delete</code> / <code>restore</code> / <code>force.delete</code>)</li><li>Assign a category when uploading or editing a document</li><li>You cannot soft-delete a category that still has documents; clear or reassign them first</li></ul><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h2><p>Open a document and use <strong>Download</strong>, or call the download endpoint. Download requires <code>documents.view</code>. Soft-deleted files are not downloadable until restored.</p><h2 id="edit-replace-file" tabindex="-1">Edit &amp; replace file <a class="header-anchor" href="#edit-replace-file" aria-label="Permalink to &quot;Edit &amp; replace file&quot;">​</a></h2><p>Edit metadata (title, description, category) from the row menu or the document page. Optionally replace the file on update — the new size must fit remaining Storage quota (only the delta counts when the new file is larger).</p><h2 id="soft-delete-restore" tabindex="-1">Soft delete &amp; restore <a class="header-anchor" href="#soft-delete-restore" aria-label="Permalink to &quot;Soft delete &amp; restore&quot;">​</a></h2><ul><li><strong>Delete</strong> soft-deletes the document row; the file remains on disk but <strong>stops counting</strong> toward Storage used bytes</li><li>Only the <strong>uploader</strong> or the <strong>workspace owner</strong> can delete or permanently delete a document (having delete permission alone is not enough for someone else’s files)</li><li>Select multiple active documents you own (or all, if you are the owner) and use <strong>Delete (N)</strong> for bulk soft delete</li><li><strong>Restore</strong> brings it back into the library and quota (blocked if restoring would exceed Storage allowance)</li><li><strong>Delete permanently</strong> removes the row and deletes the object from storage (trash / Deleted only) — same ownership rule</li><li>In <strong>Deleted only</strong>, select rows and use <strong>Delete permanently (N)</strong> for bulk permanent delete</li><li>Soft-deleted documents older than your workspace <strong>trash retention</strong> (Settings → General) are purged automatically — including the file on disk (<code>trash:purge-expired</code>). Retention <code>0</code> keeps trash forever.</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Typical use</th></tr></thead><tbody><tr><td><code>documents.view</code></td><td>List, open, download, stats, browse categories</td></tr><tr><td><code>documents.create</code></td><td>Upload documents; create categories</td></tr><tr><td><code>documents.update</code></td><td>Edit metadata / replace file; update categories</td></tr><tr><td><code>documents.delete</code></td><td>Soft delete documents and empty categories</td></tr><tr><td><code>documents.restore</code></td><td>Restore soft-deleted rows; trash filters</td></tr><tr><td><code>documents.force.delete</code></td><td>Permanently delete (owner/superadmin only by default)</td></tr></tbody></table><h2 id="storage-quota" tabindex="-1">Storage quota <a class="header-anchor" href="#storage-quota" aria-label="Permalink to &quot;Storage quota&quot;">​</a></h2><p>Every active document’s <code>size_bytes</code> counts toward the workspace Storage allowance (along with Team Chat attachments, feedback screenshots, and lead imports). Soft-deleted documents are excluded from used bytes. If upload fails with a quota error, free space or upgrade a Storage pack — see <a href="/user-guide/storage">Storage</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/user-guide/documents-overview">Documents overview</a></li><li><a href="/user-guide/storage">Storage</a></li></ul>',27)])])}const g=t(s,[["render",n]]);export{h as __pageData,g as default};
